<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Shop dashboard</title><style>:root{color-scheme:dark;--bg:#08111b;--c:#111c2b;--i:#edf5ff;--m:#9bb0c9;--l:#283b54;--a:#29d8d0;--r:#ef657e;--y:#e7ad44}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#133744,transparent 34%),var(--bg);color:var(--i);font:14px/1.5 system-ui}main{max-width:1240px;margin:auto;padding:42px 26px 80px}.top{display:flex;justify-content:space-between;gap:16px;align-items:start}.eye{color:var(--a);font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.top h1{font-size:38px;line-height:1.05;margin:10px 0}.m{color:var(--m)}section{margin:22px 0;padding:22px;border:1px solid var(--l);border-radius:18px;background:rgba(17,28,43,.94)}button,input,select{font:inherit}button{border:0;border-radius:9px;padding:10px 14px;background:var(--a);color:#071218;font-weight:850;cursor:pointer}.out,.tab{background:#101a28;border:1px solid var(--l);color:var(--m)}.tab.active{background:rgba(41,216,208,.13);border-color:var(--a);color:var(--a)}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.filters{display:grid;grid-template-columns:1.6fr 1fr 1fr auto;gap:10px;align-items:end}label{display:grid;gap:6px;font-weight:750}input,select{width:100%;border:1px solid #344c69;border-radius:9px;padding:11px;background:#0a1421;color:var(--i)}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{padding:16px;border:1px solid var(--l);border-radius:13px;background:#0b1522}.lab{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--m);font-weight:800}.num{font-size:27px;font-weight:900;line-height:1.15;margin-top:8px}.good{color:var(--a)}.bad{color:var(--r)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #23354d}.row:last-child{border:0}.bar{height:5px;border-radius:9px;background:#203249;margin-top:7px;overflow:hidden}.bar span{display:block;height:100%;border-radius:inherit;background:var(--a)}.notice{border-color:var(--y);color:#ffe0a4}.error{border-color:var(--r);color:#ffc5d0}.detail{display:grid;grid-template-columns:1fr auto;gap:10px;padding:12px 0;border-bottom:1px solid #23354d}.pill{font-size:11px;font-weight:800;padding:4px 7px;border-radius:99px;background:#203249;color:#dbe9fb}@media(max-width:820px){main{padding:28px 16px}.filters,.cards,.grid{grid-template-columns:1fr}.top h1{font-size:30px}}</style></head><body><main>
<div class="top"><div><div class="eye">GoCommerce TikTok Analytics</div><h1>{{ $client->name }}</h1><p class="m">Seller-owned Shop performance · read-only commercial intelligence</p></div><form method="POST" action="{{ route('client.logout') }}">@csrf<button class="out">Sign out</button></form></div>
<nav class="tabs">@foreach($shops as $shop)<a href="{{ route('client.dashboard',['shop_id'=>$shop->shop_id,'start_date'=>$startDate,'end_date'=>$endDate]) }}"><button type="button" class="tab {{ $selectedShop?->id===$shop->id?'active':'' }}">{{ $shop->name }} · {{ $shop->region }}</button></a>@endforeach</nav>
