<section><div class="eye">Period summary</div><h2 style="margin:7px 0">{{ data_get($summary,'date_range.start') }} to {{ data_get($summary,'date_range.end_exclusive') }} exclusive</h2><p class="m">Source: {{ $summary['source'] ?? 'TikTok Shop Open API' }} · {{ data_get($summary,'date_range.timezone','Asia/Manila') }} · {{ $summary['attribution'] ?? 'Total Shop data, not TikTok Ads-attributed revenue.' }}</p><div class="cards"><div class="card"><div class="lab">Net order value</div><div class="num good">{{ number_format((float)($dash['nmv'] ?? 0),2) }} {{ $currency }}</div><small class="m">GMV less canceled value; refunds excluded</small></div><div class="card"><div class="lab">Calculated GMV</div><div class="num">{{ number_format((float)($orders['calculated_gmv'] ?? 0),2) }} {{ $currency }}</div><small class="m">SKU subtotal + platform discount</small></div><div class="card"><div class="lab">Orders</div><div class="num">{{ number_format((int)($status['records_scanned'] ?? 0)) }}</div><small class="m">{{ number_format((int)($dash['completed_orders'] ?? 0)) }} delivered / completed</small></div><div class="card"><div class="lab">AOV</div><div class="num">{{ number_format((float)($dash['aov'] ?? 0),2) }} {{ $currency }}</div><small class="m">Non-canceled orders</small></div></div></section>
<div class="cards"><div class="card"><div class="lab">Cancel rate</div><div class="num bad">{{ number_format((float)($dash['cancel_rate_by_value'] ?? 0),2) }}%</div><small class="m">{{ number_format((float)($dash['canceled_value'] ?? 0),2) }} {{ $currency }}</small></div><div class="card"><div class="lab">Platform subsidy</div><div class="num" style="color:var(--y)">{{ number_format((float)($dash['platform_subsidy'] ?? 0),2) }}</div><small class="m">{{ $currency }} · line-item discounts</small></div><div class="card"><div class="lab">Units</div><div class="num">{{ number_format((int)($dash['units'] ?? 0)) }}</div><small class="m">Non-canceled line items</small></div><div class="card"><div class="lab">Data quality</div><div class="num {{ ($orders['complete'] ?? false)?'good':'bad' }}">{{ ($orders['complete'] ?? false)?'Complete':'Check' }}</div><small class="m">{{ number_format((int)($status['pages_fetched'] ?? 0)) }} pages · matched: {{ ($orders['reported_total_matches'] ?? false)?'yes':'no' }}</small></div></div>
<div class="grid"><section><div class="eye">Best-selling SKUs</div><h2>Top products by operational NMV</h2>@forelse(array_slice($dash['top_products'] ?? [],0,10) as $item)<div class="row"><div><strong>{{ $item['name'] }}</strong><br><small class="m">{{ $item['sku'] }} · {{ number_format((int)$item['units']) }} units</small><div class="bar"><span style="width:{{ min(100,($item['value']/max(1,($dash['top_products'][0]['value'] ?? 1)))*100) }}%"></span></div></div><strong>{{ number_format((float)$item['value'],2) }}</strong></div>@empty<p class="m">No SKU details were returned.</p>@endforelse</section><section><div class="eye">Cancellations</div><h2>Top canceled SKUs</h2>@forelse(array_slice($dash['top_cancel_skus'] ?? [],0,10) as $item)<div class="row"><div><strong>{{ $item['name'] }}</strong><br><small class="m">{{ $item['sku'] }} · {{ number_format((int)$item['units']) }} units</small></div><strong class="bad">{{ number_format((float)$item['value'],2) }}</strong></div>@empty<p class="m">No canceled SKU detail was returned.</p>@endforelse</section></div>
<div class="grid"><section><div class="eye">Order operations</div><h2>Payment methods</h2>@forelse(array_slice($dash['payment_methods'] ?? [],0,8) as $item)<div class="row"><span>{{ $item['name'] }}</span><strong>{{ number_format((int)$item['orders']) }} orders</strong></div>@empty<p class="m">TikTok did not return payment-method data for this Shop/period.</p>@endforelse</section><section><div class="eye">Coarse geography</div><h2>Country, region, or city</h2>@forelse(array_slice($dash['locations'] ?? [],0,8) as $item)<div class="row"><span>{{ $item['name'] }}</span><strong>{{ number_format((int)$item['orders']) }} orders</strong></div>@empty<p class="m">No coarse location was returned. Exact addresses are never stored or shown.</p>@endforelse</section></div>
<div class="grid"><section><div class="eye">Cancellation reasons</div><h2>Why orders cancel</h2>@forelse(array_slice($dash['cancel_reasons'] ?? [],0,8) as $item)<div class="row"><span>{{ $item['name'] }}</span><strong class="bad">{{ number_format((int)$item['orders']) }}</strong></div>@empty<p class="m">TikTok did not return cancellation-reason data.</p>@endforelse</section><section><div class="eye">Not connected yet</div><h2>Ads & affiliate performance</h2><p class="m">Ads spend, attributed revenue, ROAS, creatives, affiliate LIVE/video, and creator rankings require the separate TikTok Ads reporting layer and Shop Affiliate endpoints. They are not estimated from total Shop orders.</p></section></div>
<section><div class="eye">Redacted order details</div><h2>Commercial review sample</h2><p class="m">Up to 100 records. Names, contact data, exact addresses, order references, payment references, and tracking details are removed.</p>@forelse($summary['order_details'] ?? [] as $detail)@php($items=is_array($detail['line_items'] ?? null)?$detail['line_items']:[])<div class="detail"><div><span class="pill">{{ $detail['status'] ?? 'UNKNOWN' }}</span>@foreach($items as $item)<div style="margin-top:8px"><strong>{{ $item['product_name'] ?? $item['product_title'] ?? $item['sku_name'] ?? 'Product detail unavailable' }}</strong><br><small class="m">SKU: {{ $item['seller_sku'] ?? $item['sku_id'] ?? 'Not returned' }} · Qty: {{ $item['quantity'] ?? $item['sku_quantity'] ?? '—' }}</small></div>@endforeach</div><div class="m">{{ $detail['city'] ?? $detail['region'] ?? $detail['country'] ?? '' }}</div></div>@empty<p class="m">No redacted order details were returned.</p>@endforelse</section>
